<script setup lang="ts">
const name=ref(''), email=ref(''), phone=ref(''), secret=ref(''), error=ref(''), loading=ref(false)
async function register(){error.value='';loading.value=true;try{await $fetch('/api/auth/register',{method:'POST',body:{name:name.value,email:email.value,phone:phone.value,password:secret.value}});await navigateTo('/account')}catch(e:any){error.value=e?.data?.statusMessage==='EMAIL_ALREADY_REGISTERED'?'Этот email уже зарегистрирован.':e?.statusCode===503?'База данных временно недоступна.':'Не удалось создать аккаунт.'}finally{loading.value=false}}
</script>
<template><div class="mx-auto max-w-md"><h1 class="text-3xl font-bold">Регистрация</h1><form class="mt-6 space-y-4" @submit.prevent="register"><input v-model="name" required placeholder="Имя" class="w-full rounded-xl border p-3"><input v-model="email" type="email" required placeholder="Email" class="w-full rounded-xl border p-3"><input v-model="phone" required placeholder="Телефон" class="w-full rounded-xl border p-3"><input v-model="secret" type="password" minlength="8" required placeholder="Пароль" class="w-full rounded-xl border p-3"><p v-if="error" class="rounded-xl bg-red-50 p-3 text-red-700">{{ error }}</p><button :disabled="loading" class="w-full rounded-xl bg-slate-900 p-3 font-semibold text-white">{{loading?'Создание...':'Создать аккаунт'}}</button></form></div></template>
